    assert.deepEqual(names(await list({ search: 'alpha board' })), ['Alpha Board', 'ALPHA  Board']);
    assert.deepEqual(names(await list({ search: 'alpha  board' })), ['Alpha Board', 'ALPHA  Board']);
    assert.deepEqual(names(await list({ search: 'älpha' })), []); // No Unicode case folding.
    assert.deepEqual(names(await list({ search: 'Älpha' })), ['Älpha']);
